/**
 * The company address (RULE-058, 178, 179): a person's `@vektorprogrammet.no` address, generated by a pure rule and
 * never guessed in a second place. The address that a person already has (imported, or typed by an administrator) is
 * kept and never regenerated; this rule names an address only for a person who has none.
 *
 * RULE-058 as the legacy `CompanyEmailMaker` has it: the first name, then the full name with dots, then the full name
 * with a number from 2 on, taking the first one that is free. Two things differ, and both are stated here:
 *
 * - The system keeps one `name` per person (spec 0006), not a first and a last name, so the "first name" is the first
 *   word of the name and the "full name" is every word, joined with dots.
 * - Legacy transliterated with `iconv` in the `nb_NO` locale, so what æ, ø and å became depended on the server (the
 *   rule's open question, confidence Medium). The table below is the glibc `nb_NO` one, and an address that already
 *   exists is never touched, so a different choice by the operator changes new addresses only.
 */
import { Array as Arr, Option, Schema } from "effect";

export const COMPANY_DOMAIN = "vektorprogrammet.no";

/** RULE-179 as a pattern: the one definition that the schema below and the database's `CHECK` on `team.group_email` share. */
export const COMPANY_EMAIL_PATTERN = /^[a-z0-9._+-]+@vektorprogrammet\.no$/u;

/** RULE-179: a lower-case address that ends in `@vektorprogrammet.no`. */
export const CompanyEmail = Schema.String.check(
  Schema.isPattern(COMPANY_EMAIL_PATTERN, {
    expected: "an address that ends in @vektorprogrammet.no",
  })
).pipe(Schema.brand("CompanyEmail"));

export type CompanyEmail = typeof CompanyEmail.Type;

/** The words of a name in the alphabet of an address: ASCII letters and digits, lower case. The glibc `nb_NO` table. */
const wordsOf = (name: string): readonly string[] =>
  Arr.filter(
    name
      .toLowerCase()
      .replaceAll("å", "aa")
      .replaceAll("æ", "ae")
      .replaceAll("ø", "o")
      .normalize("NFD")
      .replaceAll(/[^a-z0-9 ]/gu, " ")
      .split(/\s+/u),
    (word) => word.length > 0
  );

const at = (local: string): string => `${local}@${COMPANY_DOMAIN}`;

/**
 * RULE-058: the address for `name` that no one in `taken` (lower-case addresses: every person's, the teams', the
 * directory's) has. `none` when the name has no letter or digit that an address can hold.
 */
export const companyEmailFor = (
  name: string,
  taken: ReadonlySet<string>
): Option.Option<CompanyEmail> => {
  const [first, ...rest] = wordsOf(name);

  if (first === undefined) {
    return Option.none();
  }

  const full = Arr.join([first, ...rest], ".");

  const plain = Arr.findFirst(
    Arr.dedupe([at(first), at(full)]),
    (address) => !taken.has(address)
  );

  // At most `taken.size` numbers are taken, so one of `taken.size + 1` is free and a number is always found.
  const numbered = () =>
    Option.map(
      Arr.findFirst(
        Arr.range(2, taken.size + 2),
        (n) => !taken.has(at(`${full}${n}`))
      ),
      (n) => at(`${full}${n}`)
    );

  return Option.map(Option.orElse(plain, numbered), (address) =>
    CompanyEmail.make(address)
  );
};
